package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import thaumcraft.api.aspects.*;
public final class Protoclay extends Item {
 static final net.neoforged.neoforge.registries.DeferredItem<Protoclay> ITEM=KamiRegistries.ITEMS.register("protoclay",Protoclay::new);
 public Protoclay(){super(new Properties().stacksTo(1).rarity(Rarity.EPIC));}static void init(){}
 static String target(net.minecraft.world.level.block.state.BlockState state){for(String type:new String[]{"pick","shovel","axe"})if(AdvancedToolMining.material(state,type))return type;return "";}
 static void update(net.minecraft.world.entity.player.Player player){var current=player.getMainHandItem();if(!(current.getItem() instanceof AdvancedTool tool)||tool.toolType().equals("sword")||!player.swinging)return;var eye=player.getEyePosition();var hit=player.level().clip(new net.minecraft.world.level.ClipContext(eye,eye.add(player.getLookAngle().scale(player.blockInteractionRange())),net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.ANY,player));if(hit.getType()!=net.minecraft.world.phys.HitResult.Type.BLOCK)return;String desired=target(player.level().getBlockState(hit.getBlockPos()));if(desired.isEmpty()||desired.equals(tool.toolType()))return;var inventory=player.getInventory();for(int slot=0;slot<inventory.getContainerSize();slot++){var stack=inventory.getItem(slot);if(stack==current||!(stack.getItem() instanceof AdvancedTool candidate)||!candidate.toolType().equals(desired))continue;inventory.setItem(inventory.selected,stack);inventory.setItem(slot,current);break;}}
 @Override public void inventoryTick(ItemStack stack,net.minecraft.world.level.Level level,net.minecraft.world.entity.Entity entity,int slot,boolean selected){if(entity instanceof net.minecraft.world.entity.player.Player player)update(player);}
 static void research(){var r=new KamiResearch("PROTOCLAY",new AspectList().add(Aspect.TOOL,2).add(Aspect.MINE,1).add(Aspect.MAN,1).add(Aspect.MECHANISM,1),12,17,5,new ItemStack(ITEM.get()));r.setParents("ICHOR_PICK_GEM");r.setParentsHidden("ICHOR_SHOVEL_GEM");r.setPages(new thaumcraft.api.research.ResearchPage("ttresearch.page.PROTOCLAY.0"),MagnetResearch.page("PROTOCLAY",thaumcraft.api.research.ResearchPage.PageType.INFUSION_CRAFTING)).registerResearchItem();ThaumicTinkererModern.INFUSION_RECIPES.add(new dev.eugheist.tc4modern.InfusionItemRecipes.Recipe("PROTOCLAY","PROTOCLAY",ITEM::get,4,new AspectList().add(Aspect.MINE,16).add(Aspect.TOOL,16),()->Items.CLAY_BALL,java.util.List.of(()->Items.DIRT,()->Items.STONE,()->Items.OAK_LOG,()->KamiResources.item(KamiResources.Kind.ENDER_SHARD))));}
}
